-- =====================================================================
-- 486_tprm_configuration_rollback.sql
--
-- Reverses 486 (TPRM configuration).
--   Drops the 486 procedures and functions; drops the configuration
--   tables when they are empty (487 and 488 rolled back first).
--
-- Turn the API / Web change off first (or deploy the previous build): the
-- TPRM screens call the procedures this drops. Roll back in reverse
-- order: 490, 489, 488, 487, 486.
-- Generated by tools/tprm/gen_rollbacks.py from the objects 486 creates.
-- SAFE TO RE-RUN. ASCII-only.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET NOEXEC OFF;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_compare;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_retire;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_version_activate;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_item_remove;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_q_item_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_rm_item_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_version_header_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_draft_check;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_new_version;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_adopt;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_create;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_version_copy;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_version_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_template_list;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_custom_values_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_custom_field_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_custom_field_list;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_delegation_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_review_rule_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_approval_rule_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_rules_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_library_override;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_library_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_library_list;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_reference_value_override;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_reference_value_save;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_config_reference_get;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_config_scope_check;
DROP PROCEDURE IF EXISTS grac_practice.sp_tprm_audit;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_custom_values;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_risk_model_version;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_template_effective;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_review_rule_effective;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_approval_rule_effective;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_library_effective;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_reference_effective;
DROP FUNCTION IF EXISTS grac_practice.fn_tprm_split_codes;
GO

-- Tables: dropped only when they hold no rows and 488 is rolled back; otherwise
-- they are kept (the procedures are gone, the data is not) and the
-- script says so. Delete the rows deliberately first to drop them.
IF OBJECT_ID('grac_practice.tprm_reference_list','U') IS NOT NULL
BEGIN
    IF OBJECT_ID('grac_practice.tprm_engagement','U') IS NULL
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_reference_list)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_reference_value)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_library_item)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_approval_rule)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_review_rule)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_approval_delegation)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_custom_field)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_custom_field_value)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template_version)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_dimension)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_factor)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_factor_option)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_band)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_tier_rule)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_section)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_question)
       AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_option)
    BEGIN
        DECLARE @fk NVARCHAR(MAX) = N'';
        SELECT @fk = @fk + N'ALTER TABLE grac_practice.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))
                         + N' DROP CONSTRAINT ' + QUOTENAME(fk.name) + N';'
        FROM sys.foreign_keys fk
        WHERE OBJECT_SCHEMA_NAME(fk.parent_object_id) = N'grac_practice'
          AND OBJECT_NAME(fk.parent_object_id) IN (N'tprm_reference_list', N'tprm_reference_value', N'tprm_library_item', N'tprm_approval_rule', N'tprm_review_rule', N'tprm_approval_delegation', N'tprm_custom_field', N'tprm_custom_field_value', N'tprm_template', N'tprm_template_version', N'tprm_rm_dimension', N'tprm_rm_factor', N'tprm_rm_factor_option', N'tprm_rm_band', N'tprm_rm_tier_rule', N'tprm_q_section', N'tprm_q_question', N'tprm_q_option');
        EXEC sp_executesql @fk;
        DROP TABLE IF EXISTS grac_practice.tprm_q_option;
        DROP TABLE IF EXISTS grac_practice.tprm_q_question;
        DROP TABLE IF EXISTS grac_practice.tprm_q_section;
        DROP TABLE IF EXISTS grac_practice.tprm_rm_tier_rule;
        DROP TABLE IF EXISTS grac_practice.tprm_rm_band;
        DROP TABLE IF EXISTS grac_practice.tprm_rm_factor_option;
        DROP TABLE IF EXISTS grac_practice.tprm_rm_factor;
        DROP TABLE IF EXISTS grac_practice.tprm_rm_dimension;
        DROP TABLE IF EXISTS grac_practice.tprm_template_version;
        DROP TABLE IF EXISTS grac_practice.tprm_template;
        DROP TABLE IF EXISTS grac_practice.tprm_custom_field_value;
        DROP TABLE IF EXISTS grac_practice.tprm_custom_field;
        DROP TABLE IF EXISTS grac_practice.tprm_approval_delegation;
        DROP TABLE IF EXISTS grac_practice.tprm_review_rule;
        DROP TABLE IF EXISTS grac_practice.tprm_approval_rule;
        DROP TABLE IF EXISTS grac_practice.tprm_library_item;
        DROP TABLE IF EXISTS grac_practice.tprm_reference_value;
        DROP TABLE IF EXISTS grac_practice.tprm_reference_list;
        PRINT '486 rollback: tables dropped.';
    END
    ELSE
        PRINT '486 rollback: configuration data exists (or 488 is still in place) -- tables kept.';
END
GO

PRINT '486 rollback complete.';
GO
